+  const char* file_path = argc > 1 ? argv[1] : nullptr;
+  bool ok = true;
+
+  std::printf("LLAMA_PROBE pointer_bits=%zu\n", sizeof(void*) * 8U);
+  if (sizeof(void*) != 8U) {
+    std::fprintf(stderr, "FAIL requires a 64-bit address space\n");
+    ok = false;
+  }
+
+#if defined(__aarch64__)
+  std::printf("LLAMA_PROBE arch=aarch64\n");
+#else
+  std::printf("LLAMA_PROBE arch=non-aarch64\n");
+  ok = false;
+#endif
+
+#if defined(__ARM_NEON) || defined(__ARM_NEON__)
+  std::printf("LLAMA_PROBE neon=yes\n");
+#else
+  std::printf("LLAMA_PROBE neon=no\n");
+  ok = false;
+#endif
+
+  timespec begin{};
+  timespec end{};
+  if (clock_gettime(CLOCK_MONOTONIC, &begin) != 0) {
+    std::fprintf(stderr, "FAIL clock_gettime errno=%d\n", errno);
+    ok = false;
+  }
+
+  constexpr int kThreadCount = 4;
+  pthread_t threads[kThreadCount]{};
+  WorkerResult results[kThreadCount]{};
+  int created = 0;
+  for (; created < kThreadCount; ++created) {
+    const int rc = pthread_create(&threads[created], nullptr, worker,
+                                  &results[created]);
+    if (rc != 0) {
+      std::fprintf(stderr, "FAIL pthread_create index=%d rc=%d\n", created,
+                   rc);
+      ok = false;
+      break;
+    }
+  }
+  for (int i = 0; i < created; ++i) {
+    const int rc = pthread_join(threads[i], nullptr);
+    if (rc != 0) {
+      std::fprintf(stderr, "FAIL pthread_join index=%d rc=%d\n", i, rc);
+      ok = false;
+    }
+  }
+  if (clock_gettime(CLOCK_MONOTONIC, &end) == 0) {
+    std::printf("LLAMA_PROBE pthread_threads=%d elapsed_ms=%.2f\n", created,
+                elapsed_ms(begin, end));
+  }
+
+  const size_t alloc_bytes =
+      static_cast<size_t>(CONFIG_APP_LLAMA_OPENVELA_PROBE_ALLOC_MB) *
+      1024U * 1024U;
+  auto* memory = static_cast<unsigned char*>(std::malloc(alloc_bytes));
+  if (memory == nullptr) {
+    std::fprintf(stderr, "FAIL malloc bytes=%zu\n", alloc_bytes);
+    ok = false;
+  } else {
+    constexpr size_t kPage = 4096;
+    for (size_t offset = 0; offset < alloc_bytes; offset += kPage) {
+      memory[offset] = static_cast<unsigned char>(offset / kPage);
+    }
+    uint64_t checksum = 0;
+    for (size_t offset = 0; offset < alloc_bytes; offset += kPage) {
+      checksum += memory[offset];
+    }
+    std::printf("LLAMA_PROBE malloc_mb=%d checksum=%" PRIu64 "\n",
+                CONFIG_APP_LLAMA_OPENVELA_PROBE_ALLOC_MB, checksum);
+    std::free(memory);
+  }
+
+  if (file_path != nullptr) {
+    FILE* file = std::fopen(file_path, "rb");
+    if (file == nullptr) {
+      std::fprintf(stderr, "FAIL fopen path=%s errno=%d\n", file_path,
+                   errno);
+      ok = false;
+    } else {
+      unsigned char buffer[64 * 1024];
+      uint64_t total = 0;
+      uint64_t checksum = 0;
+      while (true) {
+        const size_t count = std::fread(buffer, 1, sizeof(buffer), file);
+        for (size_t i = 0; i < count; ++i) checksum += buffer[i];
+        total += count;
+        if (count != sizeof(buffer)) {
+          if (std::ferror(file)) {
+            std::fprintf(stderr, "FAIL fread errno=%d\n", errno);
+            ok = false;
+          }
+          break;
+        }
+      }
+      std::fclose(file);
+      std::printf("LLAMA_PROBE file_bytes=%" PRIu64
+                  " file_checksum=%" PRIu64 "\n",
+                  total, checksum);
+    }
+  } else {
+    std::printf("LLAMA_PROBE file_test=skipped pass_model_path_as_argv1\n");
+  }
+
+  std::printf("LLAMA_PROBE result=%s\n", ok ? "PASS" : "FAIL");
+  return ok ? EXIT_SUCCESS : EXIT_FAILURE;
